ValidationRule.errorConditionFormula:
If( AND(
NOT(
OR(
$User.Bypass_VR__c = TRUE,
$Profile.Name='Xendit API Profile',
$Profile.Name='System Administrator',
$Profile.Name='Xendit Sales Ops Profile'
)
),
ISCHANGED(StageName),
ISPICKVAL(StageName,'Qualification'),
OR(
AND(
ISPICKVAL(PRIORVALUE(StageName),'Closed Lost'),
ISPICKVAL( Reason_Lost_Opp__c ,'Dead - No Opportunity')
),
No_Opportunity_Lost_Flag__c 
)


) , true,false
)
